const e = $input.first().json;
const KNOWN = ['ERR-CONSENT-DECLINED','ERR-INVALID-FILE-TYPE','ERR-DUPLICATE-SUBMISSION',
  'ERR-PDF-UNREADABLE','ERR-OCR-EMPTY','ERR-PARSER-FAILED','ERR-EVIDENCE-RATIO-LOW',
  'ERR-ANALYST-TIMEOUT','ERR-GAPENGINE-FAILED','ERR-RANKER-FAILED','ERR-NO-CANDIDATE-FOUND',
  'ERR-REPORTER-FAILED','ERR-SHEETS-WRITE-FAILED'];   // enum_error_type
const msg = e.execution?.error?.message || '';
const code = KNOWN.find(k => msg.includes(k)) || 'ERR-UNCLASSIFIED';
return [{ json: { submission_id: e.execution?.customData?.submission_id || '',
  role_id: '', stage: e.execution?.lastNodeExecuted || '', error_type: code,
  error_message: msg.slice(0,500), node: e.execution?.lastNodeExecuted || '',
  execution_id: e.execution?.id || '', logged_at: new Date().toISOString() } }];
